//! Engine tests on fixtures generated by the Scala side
//! (`sbt "Test/runMain spinaltrace.FixtureGen ../spinaltrace-rs/tests/fixtures"` in spinaltrace/).
use std::path::{Path, PathBuf};

use spinaltrace_rs::{
    graphbuilder::{CriterionType, StopAt},
    pdg_spec::{ExportablePDG, PDGSpecEdgeKind, PDGSpecNodeKind},
    pipeline::{self, TraceRequest},
};

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures").join(name)
}

fn meta_time(name: &str, key: &str) -> u64 {
    let s = std::fs::read_to_string(fixture(name).join("meta.json")).unwrap();
    let v: serde_json::Value = serde_json::from_str(&s).unwrap();
    v[key].as_f64().unwrap() as u64
}

/// Line of `text` in an example source file (after `after`, if given).
fn line_of(file: &str, text: &str, after: &str) -> u32 {
    let p = Path::new(env!("CARGO_MANIFEST_DIR")).join("../examples/src/spinaltrace/examples").join(file);
    let src = std::fs::read_to_string(p).unwrap();
    let lines: Vec<&str> = src.lines().collect();
    let start = if after.is_empty() { 0 } else { lines.iter().position(|l| l.contains(after)).unwrap() };
    (lines.iter().skip(start).position(|l| l.contains(text)).expect(text) + start + 1) as u32
}

fn trace(name: &str, criterion: CriterionType, at: Option<u64>, typed: bool) -> ExportablePDG {
    let dir = fixture(name);
    let mut req = TraceRequest::new(dir.join("pdg.json"), dir.join("wave.vcd"), criterion);
    if let Some(t) = at { req.stop_at = StopAt::Time(t); }
    if typed { req.hgldd_path = Some(dir.join("hgldd")); }
    pipeline::trace(&req).unwrap()
}

fn lines(d: &ExportablePDG, file: &str) -> Vec<u32> {
    d.vertices.iter().filter(|v| v.file.ends_with(file)).map(|v| v.line).collect()
}

fn has_edge(d: &ExportablePDG, from: impl Fn(&spinaltrace_rs::pdg_spec::ExportablePDGNode) -> bool,
            to: impl Fn(&spinaltrace_rs::pdg_spec::ExportablePDGNode) -> bool, kind: PDGSpecEdgeKind) -> bool {
    d.edges.iter().any(|e| e.kind == kind && from(&d.vertices[e.from as usize]) && to(&d.vertices[e.to as usize]))
}

#[test]
fn gcd_trace_reaches_load_and_subtractions() {
    let d = trace("gcd", CriterionType::Signal("io.result".into()), Some(meta_time("gcd", "done")), false);
    let l = lines(&d, "Gcd.scala");
    for text in ["io.result        := x", "x := x - y", "y := y - x", "when(x > y)", "x := io.a", "when(io.loadValues)"] {
        assert!(l.contains(&line_of("Gcd.scala", text, "")), "{} missing\n{}", text, pipeline::summary(&d));
    }
    assert!(!l.contains(&line_of("Gcd.scala", "io.resultIsValid := y === 0", "")));
    let top = d.vertices.iter().filter(|v| v.line == line_of("Gcd.scala", "io.result        := x", "")).max_by_key(|v| v.timestamp).unwrap();
    assert!(top.sim_data.as_deref().unwrap_or("").starts_with("12 "), "{:?}", top.sim_data);
    assert!(has_edge(&d, |v| v.name == "connect_x", |v| v.kind == PDGSpecNodeKind::ControlFlow, PDGSpecEdgeKind::Conditional));
    assert!(!d.edges.iter().any(|e| e.kind == PDGSpecEdgeKind::Index));
}

#[test]
fn gcd_typed_values_from_hgldd() {
    let d = trace("gcd", CriterionType::Signal("io_result".into()), Some(meta_time("gcd", "done")), true);
    let x = d.vertices.iter().find(|v| v.name == "connect_x").unwrap();
    assert!(x.sim_data.as_deref().unwrap_or("").starts_with("Reg UInt(32 bits)"), "{:?}", x.sim_data);
}

#[test]
fn switch_takes_the_matching_case_or_default() {
    let sub = line_of("Features.scala", "acc := io.a - io.b", "");
    let add = line_of("Features.scala", "acc := io.a + io.b", "");
    let dflt = line_of("Features.scala", "default {", "") + 1; // `acc := io.a`
    let sw = line_of("Features.scala", "switch(io.op)", "");
    let d = trace("switch_enum", CriterionType::Signal("io_result".into()), Some(meta_time("switch_enum", "sub")), false);
    let l = lines(&d, "Features.scala");
    assert!(l.contains(&sub) && l.contains(&sw) && !l.contains(&add) && !l.contains(&dflt), "{}", pipeline::summary(&d));
    let d = trace("switch_enum", CriterionType::Signal("io_result".into()), Some(meta_time("switch_enum", "default")), false);
    let l = lines(&d, "Features.scala");
    assert!(l.contains(&dflt) && !l.contains(&sub) && !l.contains(&add), "{}", pipeline::summary(&d));
}

#[test]
fn vec_dynamic_index_edges_and_right_write() {
    let d = trace("vec_dynamic", CriterionType::Signal("io_rdData".into()), Some(meta_time("vec_dynamic", "read")), false);
    let wr = line_of("Features.scala", "regs(io.wrIdx) := io.wrData", "");
    let rd = line_of("Features.scala", "io.rdData := regs(io.rdIdx)", "");
    assert!(has_edge(&d, |v| v.line == rd, |v| v.name == "input_io_rdIdx", PDGSpecEdgeKind::Index), "{}", pipeline::summary(&d));
    assert!(has_edge(&d, |v| v.line == wr, |v| v.name == "input_io_wrIdx", PDGSpecEdgeKind::Index));
    let writes: Vec<_> = d.vertices.iter().filter(|v| v.line == wr).collect();
    assert_eq!(writes.len(), 1);
    assert!(writes[0].sim_data.as_deref().unwrap_or("").starts_with("85 "));
}

#[test]
fn reset_pulse_restarts_the_chain() {
    let init = line_of("Features.scala", "Reg(UInt(8 bits)) init (5)", "");
    let inc = line_of("Features.scala", "counter := counter + 1", "");
    let d = trace("reset_counter", CriterionType::Signal("io_count".into()), Some(meta_time("reset_counter", "after")), false);
    let inits: Vec<i64> = d.vertices.iter().filter(|v| v.line == init).map(|v| v.timestamp).collect();
    let incs: Vec<i64> = d.vertices.iter().filter(|v| v.line == inc).map(|v| v.timestamp).collect();
    assert_eq!(inits.len(), 1, "{}", pipeline::summary(&d));
    assert!(inits[0] > 3 && incs.iter().all(|t| *t > inits[0]) && incs.len() == 2, "{}", pipeline::summary(&d));
    let d = trace("reset_counter", CriterionType::Signal("io_count".into()), Some(meta_time("reset_counter", "before")), false);
    assert!(d.vertices.iter().filter(|v| v.line == init).all(|v| v.timestamp <= 0));
}

#[test]
fn sync_mem_read_depends_on_the_write_of_its_address() {
    let d = trace("sync_mem", CriterionType::Signal("io_rdData".into()), Some(meta_time("sync_mem", "read")), false);
    let rd = line_of("Features.scala", "io.rdData := mem.readSync(io.rdAddr)", "");
    let wr = line_of("Features.scala", "mem.write(io.wrAddr, io.wrData)", "");
    assert!(has_edge(&d, |v| v.line == rd, |v| v.line == wr, PDGSpecEdgeKind::Data), "{}", pipeline::summary(&d));
    assert!(has_edge(&d, |v| v.line == rd, |v| v.name == "input_io_rdAddr", PDGSpecEdgeKind::Index));
    assert_eq!(d.vertices.iter().filter(|v| v.line == wr).count(), 1);
}

#[test]
fn line_and_statement_criteria() {
    let at = Some(meta_time("gcd", "done"));
    let l = line_of("Gcd.scala", "x := x - y", "");
    let d = trace("gcd", CriterionType::Line("Gcd.scala".into(), l), at, false);
    assert!(lines(&d, "Gcd.scala").contains(&l));
    let d = trace("gcd", CriterionType::Statement("connect_io_result".into()), at, false);
    assert!(d.vertices.iter().any(|v| v.name == "connect_io_result"));
}
